import{_ as a,a0 as r,w as l,s as p,ao as d,I as n,x as t,a1 as i,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何重置 RHEL7/CentOS7 系统的密码 | LCTT x X-CMD","titleTemplate":false,"description":"如何重置 RHEL7/CentOS7 系统的密码 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何重置 RHEL7/CentOS7 系统的密码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何重置 RHEL7/CentOS7 系统的密码 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20160908 How to reset the root password in RHEL7CentOS7Scientific Linux 7- based systems","title":"如何重置 RHEL7/CentOS7 系统的密码","tag":"201702","desc":""},"relativePath":"201702/20160908 How to reset the root password in RHEL7CentOS7Scientific Linux 7- based systems.md","filePath":"[post].md"}'),h={name:"201702/20160908 How to reset the root password in RHEL7CentOS7Scientific Linux 7- based systems.md"};function g(c,s,u,k,b,f){const e=r("Link");return l(),p("div",null,[s[13]||(s[13]=d('<h1 id="如何重置-rhel7-centos7-系统的密码" tabindex="-1">如何重置 RHEL7/CentOS7 系统的密码 <a class="header-anchor" href="#如何重置-rhel7-centos7-系统的密码" aria-label="Permalink to “如何重置 RHEL7/CentOS7 系统的密码”">​</a></h1><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p><strong>目的</strong></p><p>在 RHEL7/CentOS7/Scientific Linux 7 中重设 root 密码。</p><p><strong>要求</strong></p><p>RHEL7 / CentOS7 / Scientific Linux 7</p><p><strong>困难程度</strong></p><p>中等</p><h3 id="指导" tabindex="-1">指导 <a class="header-anchor" href="#指导" aria-label="Permalink to “指导”">​</a></h3><p>RHEL7 的世界发生了变化，重置 root 密码的方式也一样。虽然中断引导过程的旧方法（init=/bin/bash）仍然有效，但它不再是推荐的。“Systemd” 使用 “rd.break” 来中断引导。让我们快速浏览下整个过程。</p><p><strong>启动进入最小模式</strong></p><p>重启系统并在内核列表页面在系统启动之前按下 <code>e</code>。你会进入编辑模式。</p><p><strong>中断启动进程</strong></p><p>在内核字符串中 - 在以 <code>linux 16 /vmlinuz- ect</code> 结尾的行中输入 <code>rd.break</code>。接着 <code>Ctrl+X</code> 重启。系统启动进入初始化内存磁盘，并挂载在 <code>/sysroot</code>。在此模式中你不需要输入密码。</p><p><strong>重新挂载文件系统以便读写</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>switch_root:/# mount -o remount,rw /sysroot/</span></span></code></pre></div><p><strong>使 /sysroot 成为根目录</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>switch_root:/# chroot /sysroot</span></span></code></pre></div><p>命令行提示符会稍微改变。</p><p><strong>修改 root 密码</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh-4.2# passwd</span></span></code></pre></div><p><strong>加载 SELinux 策略</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh-4.2# load_policy -i</span></span></code></pre></div><p><strong>在 /etc/shadow 中设置上下文类型</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh-4.2# chcon -t shadow_t /etc/shadow</span></span></code></pre></div><p>注意：你可以通过如下创建 <code>autorelabel</code> 文件的方式来略过最后两步，但自动重建卷标会花费很长时间。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh-4.2# touch /.autorelabel</span></span></code></pre></div><p>因为这个原因，尽管它更简单，它应该作为“懒人选择”，而不是建议。</p><p><strong>退出并重启</strong></p><p>退出并重启并用新的 root 密码登录。</p><hr>',31)),n("p",null,[s[1]||(s[1]=t("via: ",-1)),i(e,{href:"https://linuxconfig.org/how-to-reset-the-root-password-in-rhel7-centos7-scientific-linux-7-based-systems"},{default:o(()=>[...s[0]||(s[0]=[t("https://linuxconfig.org/how-to-reset-the-root-password-in-rhel7-centos7-scientific-linux-7-based-systems",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=t("作者：",-1)),i(e,{href:"https://linuxconfig.org/how-to-reset-the-root-password-in-rhel7-centos7-scientific-linux-7-based-systems"},{default:o(()=>[...s[2]||(s[2]=[t("Rado Folwarczny",-1)])]),_:1}),s[6]||(s[6]=t(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:o(()=>[...s[3]||(s[3]=[t("geekpi",-1)])]),_:1}),s[7]||(s[7]=t(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[4]||(s[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[8]||(s[8]=[t("LCTT",-1)])]),_:1}),s[11]||(s[11]=t(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:o(()=>[...s[9]||(s[9]=[t("Linux中国",-1)])]),_:1}),s[12]||(s[12]=t(" 荣誉推出",-1))])])}const y=a(h,[["render",g]]);export{x as __pageData,y as default};
